'use client';

/* ============================================================
 * ServicePage = the layout shared by ALL service pages.
 * You normally do NOT edit this file.
 * Texts + pictures of one page are in its own file:
 *   app/services/<name>/page.tsx
 * (top strip, menu, hero + booking form, cars and footer are the
 *  same components as the Home page, so a change there = every page)
 * ============================================================ */

import { useEffect } from 'react';
import {
  Check, Plane, Users, MapPin, Briefcase, Star, Car, Phone, Clock, Shield, CalendarCheck, FileText, Crown,
} from 'lucide-react';
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import Header from './Header';
import Hero from './Hero';
import CarGallery from './CarGallery';
import BookingCTA from './BookingCTA';
import Footer from './Footer';

type T = { en: string; ar: string }; // every text has an English + an Arabic version

/* Icon names you can write in a page file (icon: '...') */
const ICONS = { check: Check, plane: Plane, users: Users, map: MapPin, briefcase: Briefcase, star: Star, car: Car, phone: Phone, clock: Clock, shield: Shield, calendar: CalendarCheck, file: FileText, crown: Crown };
export type IconName = keyof typeof ICONS;

export interface ServiceData {
  slug: string; // same as the folder name
  service: string; // service chosen in the booking form (a value of SERVICES in Hero.tsx)
  slides: string[]; // hero background pictures (sliding)
  hero: { badge: T; title: { en: [string, string]; ar: [string, string] }; text: T };
  overview: { badge: T; title: T; paragraphs: T[]; points: T[] };
  included: { icon: IconName; title: T; text: T }[]; // "What is included" cards (add / remove freely)
  steps: { title: T; text: T }[]; // "How it works"
}

function Eyebrow({ text }: { text: string }) {
  return (
    <div className="inline-flex items-center gap-1.5 text-[11px] sm:text-xs font-bold uppercase tracking-widest text-[#d9a036]">
      <span className="w-6 h-[2px] bg-[#d9a036]" />
      <span>{text}</span>
    </div>
  );
}

export default function ServicePage({ data }: { data: ServiceData }) {
  const currentLang = useSelector((state: RootState) => state.language.lang);
  const isAr = currentLang === 'AR';
  const L = (t: T) => (isAr ? t.ar : t.en);

  // Tell the browser the page language/direction (same as the Home page)
  useEffect(() => {
    document.documentElement.lang = isAr ? 'ar' : 'en';
    document.documentElement.dir = isAr ? 'rtl' : 'ltr';
  }, [isAr]);

  return (
    <main className={`min-h-screen bg-gray-50 ${isAr ? 'rtl' : 'ltr'}`} dir={isAr ? 'rtl' : 'ltr'}>
      <Header />

      {/* 1. Hero: sliding pictures of THIS page + information (left) + booking form (right, service already chosen) */}
      <Hero key={data.slug} slides={data.slides} service={data.service} badge={data.hero.badge} title={data.hero.title} text={data.hero.text} points={data.overview.points} />

      {/* 2. Overview: text + picture */}
      <section className="py-16 sm:py-20 bg-white" dir={isAr ? 'rtl' : 'ltr'}>
        <div className="w-[90%] max-w-[2000px] mx-auto grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-14 items-center">
          <div className="space-y-5">
            <Eyebrow text={L(data.overview.badge)} />
            <h2 className="text-2xl sm:text-3xl lg:text-4xl font-black text-gray-900 tracking-tight leading-tight">{L(data.overview.title)}</h2>
            {data.overview.paragraphs.map((p, i) => (
              <p key={i} className="text-gray-600 text-sm leading-relaxed font-medium">{L(p)}</p>
            ))}
          </div>

          {/* Uses the 2nd slide picture, so a new picture there changes this too */}
          <div className="relative rounded-2xl overflow-hidden shadow-xl border border-gray-100 aspect-[16/10] bg-gray-100">
            <img src={data.slides[1] ?? data.slides[0]} alt="" loading="lazy" className="absolute inset-0 w-full h-full object-cover" />
          </div>
        </div>
      </section>

      {/* 3. What is included */}
      <section className="py-16 sm:py-20 bg-gray-50/50" dir={isAr ? 'rtl' : 'ltr'}>
        <div className="w-[90%] max-w-[2000px] mx-auto">
          <div className="text-center space-y-2 mb-12">
            <div className="inline-flex"><Eyebrow text={isAr ? 'ما يتضمنه' : 'WHAT IS INCLUDED'} /></div>
            <h2 className="text-2xl sm:text-3xl lg:text-4xl font-black text-gray-900 tracking-tight">
              {isAr ? 'كل ما تحتاجه في خدمة واحدة' : 'Everything You Need, In One Service'}
            </h2>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {data.included.map((item, i) => {
              const Icon = ICONS[item.icon] ?? Check;
              return (
                <div key={i} className="bg-white rounded-2xl border border-gray-100 p-7 shadow-sm hover:shadow-md transition-all duration-300 group">
                  <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[#f3d38c] to-[#d9a036] flex items-center justify-center shadow-md group-hover:scale-105 transition-transform duration-300 mb-5">
                    <Icon className="w-7 h-7 text-white stroke-[2.2]" />
                  </div>
                  <h3 className="text-base sm:text-lg font-bold text-gray-900 mb-2">{L(item.title)}</h3>
                  <p className="text-xs sm:text-[13px] text-gray-500 leading-relaxed font-medium">{L(item.text)}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* 4. How it works */}
      <section className="py-16 sm:py-20 bg-white" dir={isAr ? 'rtl' : 'ltr'}>
        <div className="w-[90%] max-w-[2000px] mx-auto">
          <div className="text-center space-y-2 mb-12">
            <div className="inline-flex"><Eyebrow text={isAr ? 'كيف تعمل الخدمة' : 'HOW IT WORKS'} /></div>
            <h2 className="text-2xl sm:text-3xl lg:text-4xl font-black text-gray-900 tracking-tight">
              {isAr ? 'من الحجز إلى الوصول' : 'From Booking To Arrival'}
            </h2>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {data.steps.map((st, i) => (
              <div key={i} className="relative bg-gray-50/70 rounded-2xl border border-gray-100 p-7 text-center">
                <div className="mx-auto w-12 h-12 rounded-full bg-[#d9a036] text-white font-black text-lg flex items-center justify-center shadow-md mb-4">{i + 1}</div>
                <h3 className="text-base font-bold text-gray-900 mb-2">{L(st.title)}</h3>
                <p className="text-xs text-gray-500 leading-relaxed font-medium">{L(st.text)}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* 5. Cars (same cards as Home). "Reserve" fills the form of THIS page */}
      <div id="car-gallery"><CarGallery /></div>

      <BookingCTA />
      <Footer />
    </main>
  );
}
